// #51da2a (b28a22ed6a85bb764151da2a) — обычный звонок при нормальной сети: плашки «החיבור חלש» нет,
// запись recording.quality_status = sufficient (не degraded). Кейс CQ-001.
// @call — ТРАТИТ кредиты OpenAI (официальный звонок ~1,5–2 мин). Обычный регресс без звонков: npm test -- --grep-invert @call.
// Один прогон без повтора (retries 0) — правило проекта L-20261014-1 (звонок — один раз).
// НЕ prod-safe: создаёт кандидата «QA-AUTO-CQ-CALL-…» (link_only), официальная попытка использована; не удаляется.
// Вариант тикета «RTT ~450 мс»: QA_CALL_FORCE_RTT_MS=450 — getStats настоящего соединения отдаёт этот RTT
// (подмена на клиенте; ожидаемое то же — плашки нет, quality_status sufficient; см. CQ-004).
import { test, expect } from '../../fixtures';
import { openWithApi, runStamp } from '../support/api';
import { createCandidateLink, launchCandidate, goToPractice, goToOfficialConfirm, tap, timerSeconds, DIALOG_WAV } from '../candidate-call/support';
import { candidateId, getReport } from '../recording/support';
import { warningBanner, watchWarning, warningStats, trackWarningEvents, expectLive } from './support';

const HASH = '#b28a22ed6a85bb764151da2a';
const LIVE_SECONDS = 90;
const FORCE_RTT_MS = Number(process.env.QA_CALL_FORCE_RTT_MS || 0);

test.describe.configure({ retries: 0 });

test.describe(`Звонок — качество при обычной сети (${HASH})`, () => {
  test(`официальный звонок ~${LIVE_SECONDS} с при нормальной сети: плашки «החיבור חלש» нет ни разу, connection_warning не отправлялся; recording.quality_status = sufficient @desktop @data @call ${HASH}`, async ({ asUser }) => {
    test.setTimeout(12 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-CQ-CALL-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}»: официальная попытка использована, не удаляется` });
    if (FORCE_RTT_MS) test.info().annotations.push({ type: 'rtt', description: `getStats: RTT подменён на ${FORCE_RTT_MS} мс` });

    const cand = await launchCandidate({ width: 390, height: 844 }, DIALOG_WAV);
    try {
      const { page, ctx, counts } = cand;
      await watchWarning(ctx);
      if (FORCE_RTT_MS) {
        // Только RTT пары кандидатов; потери и буфер — настоящие. Строкой JS, без транспиляции.
        await ctx.addInitScript({
          content: `(() => {
            const P = window.RTCPeerConnection && window.RTCPeerConnection.prototype;
            if (!P) return;
            const orig = P.getStats;
            P.getStats = async function (...a) {
              const r = await orig.apply(this, a);
              const out = new Map();
              r.forEach((v, k) => out.set(k, v.type === 'candidate-pair' ? Object.assign({}, v, { currentRoundTripTime: ${FORCE_RTT_MS / 1000} }) : v));
              return out;
            };
          })();`,
        });
      }
      const events = trackWarningEvents(page);
      let endBody: { recording_quality?: { input_level?: number | null; packet_loss?: number | null; latency_ms?: number | null } } | undefined;
      page.on('request', (r) => {
        if (r.method() === 'POST' && r.url().includes('/functions/v1/end-candidate-attempt')) {
          try {
            endBody = r.postDataJSON();
          } catch {
            /* пусто */
          }
        }
      });

      await goToPractice(page, link);
      await goToOfficialConfirm(page);
      await tap(page, 'מוכן, מתחילים');
      await expectLive(page);
      expect(counts.voice, 'start-voice-session').toBe(1);

      // ~90 с живого звонка — ожидание по таймеру звонка (обратный отсчёт), без фиксированных пауз.
      const t0 = await timerSeconds(page);
      await expect
        .poll(() => timerSeconds(page), { message: `таймер не прошёл ${LIVE_SECONDS} с`, timeout: (LIVE_SECONDS + 60) * 1000, intervals: [2_000] })
        .toBeLessThanOrEqual(t0 - LIVE_SECONDS);
      await expectLive(page);

      // Источник: AC «שיחה תקינה בחיבור רגיל נשמרת … ובלי התרעת חיבור קבועה»; Figma 633:987 — звонок без плашки.
      const w = await warningStats(page);
      expect(w.count, `плашка «החיבור חלש» появлялась ${w.count} раз(а), всего ${Math.round(w.totalMs / 1000)} с; события: ${JSON.stringify(events)}`).toBe(0);
      await expect(warningBanner(page)).toHaveCount(0);
      expect(events, 'candidate_record_event connection_warning на нормальной сети').toEqual([]);

      const ended = page.waitForResponse((r) => r.url().includes('/functions/v1/end-candidate-attempt') && r.request().method() === 'POST', { timeout: 90_000 });
      await tap(page, 'לסיים שיחה');
      await tap(page, 'לאשר סיום שיחה');
      expect((await ended).ok(), 'end-candidate-attempt').toBe(true);
      await expect(page.getByText('הסימולציה הושלמה').first()).toBeVisible({ timeout: 90_000 });

      // Источник: «מצב נדרש» — «איכות ההקלטה נמדדת לפי מה שנלכד בפועל»: клиент отправляет замеры записи.
      const q = endBody?.recording_quality;
      expect(q, 'recording_quality в end-candidate-attempt').toBeTruthy();
      expect(q!.packet_loss ?? 0, 'packet_loss звонка на нормальной сети').toBeLessThanOrEqual(0.2);
      test.info().annotations.push({ type: 'recording_quality', description: JSON.stringify(q) });
    } finally {
      await cand.browser.close();
    }

    // Источник: AC «…נשמרת עם איכות הקלטה מספקת»; F-36 треб.7 «איכות ההקלטה … נדרשת להיות מספקת».
    const api = await openWithApi(business, '/candidates');
    const id = await candidateId(api, name);
    let status = '';
    await expect
      .poll(async () => {
        const r = (await getReport(api, id)) as { recording?: { quality_status?: string | null } };
        return (status = r.recording?.quality_status || '');
      }, { message: 'recording.quality_status не появился', timeout: 5 * 60_000, intervals: [5_000] })
      .not.toBe('');
    expect(status, 'recording.quality_status').toBe('sufficient');
  });
});
